DROP TABLE IF EXISTS `daily_summaries`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `daily_summaries` (
  `id` int NOT NULL AUTO_INCREMENT,
  `summary_date` date NOT NULL,
  `content` text COLLATE utf8mb4_unicode_ci NOT NULL,
  `stats` json DEFAULT NULL,
  `provider` varchar(40) COLLATE utf8mb4_unicode_ci NOT NULL,
  `model` varchar(80) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `created_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `idx_summary_date` (`summary_date`)
) ENGINE=InnoDB AUTO_INCREMENT=2 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

LOCK TABLES `daily_summaries` WRITE;
/*!40000 ALTER TABLE `daily_summaries` DISABLE KEYS */;
INSERT INTO `daily_summaries` VALUES (1,'2026-11-03','Top priorities today\n- #5 Investigate and resolve 502 error (due: N/A)\n- #13 Secure staging admin panel (due: 2026-10-29)\n- #9 Investigate and fix payment gateway error (due: N/A)\n- #16 Provide revised delivery timeline (due: 2026-11-02)\n- #20 Share Greenleaf store staging URL and login credentials (due: 2026-11-02)\n\nOverdue / at risk\n- Overdue: #4 (due 2026-10-28), #13 (due 2026-10-29), #1 (due 2026-10-30), #10 (due 2026-10-30), #16 (due 2026-11-02), #20 (due 2026-11-02).\n- At risk: #27 and #28 (due 2026-11-04).\n\nWaiting on replies\n- 20 messages awaiting reply, including high-priority threads from Karthik Reddy (502 error), Hannah Müller (admin security), Pradeep Joshi (delivery timeline), Meera Iyer (invoice issue), and Priya Nair (Diwali copy).\n\nQuick wins\n- #27 Confirm attendance for Sprint Planning\n- #28 Add agenda items for Sprint Planning\n- #15 Confirm design review reschedule','{\"open\": 28, \"overdue\": 6, \"completed\": 0}','gemini','gemini-3.5-flash','2026-11-03 06:36:18');
/*!40000 ALTER TABLE `daily_summaries` ENABLE KEYS */;
UNLOCK TABLES;
DROP TABLE IF EXISTS `import_batches`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `import_batches` (
  `id` int NOT NULL AUTO_INCREMENT,
  `source` enum('json','manual','gmail') COLLATE utf8mb4_unicode_ci NOT NULL,
  `filename` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `total_count` int NOT NULL DEFAULT '0',
  `imported` int NOT NULL DEFAULT '0',
  `skipped` int NOT NULL DEFAULT '0',
  `failed` int NOT NULL DEFAULT '0',
  `errors` json DEFAULT NULL,
  `created_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=2 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

