DROP TABLE IF EXISTS `message_analyses`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `message_analyses` (
  `message_id` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL,
  `summary` text COLLATE utf8mb4_unicode_ci NOT NULL,
  `category` varchar(40) COLLATE utf8mb4_unicode_ci NOT NULL,
  `intent` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `priority` enum('high','medium','low') COLLATE utf8mb4_unicode_ci NOT NULL,
  `requires_response` tinyint(1) NOT NULL DEFAULT '0',
  `requires_action` tinyint(1) NOT NULL DEFAULT '0',
  `sentiment` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `suggested_reply` text COLLATE utf8mb4_unicode_ci,
  `reasoning` text COLLATE utf8mb4_unicode_ci,
  `provider` varchar(40) COLLATE utf8mb4_unicode_ci NOT NULL,
  `model` varchar(80) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `analyzed_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`message_id`),
  KEY `idx_analysis_category` (`category`),
  KEY `idx_analysis_priority` (`priority`),
  CONSTRAINT `fk_analysis_message` FOREIGN KEY (`message_id`) REFERENCES `messages` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

LOCK TABLES `message_analyses` WRITE;
/*!40000 ALTER TABLE `message_analyses` DISABLE KEYS */;
INSERT INTO `message_analyses` VALUES ('MSG001','Priya Nair submitted the final text and promo code DIWALI20 for the Diwali sale banner, requesting the homepage hero banner be updated by 30 October.','client_request','Update homepage hero banner with Diwali sale copy and promo code','high',1,1,'neutral','Dear Priya,\n\nThank you for sending over the final Diwali sale banner text and the promo code DIWALI20. Our design and development team is currently reviewing the content from the attached document and testing the layout to ensure the character count works seamlessly on mobile screens. We will have the homepage hero banner updated and live prior to October 30th as requested.\n\nWe will reach out immediately if any mobile layout adjustments are needed.\n\nBest regards,\nActionFlow Team','The request has an explicit deadline of 30 October 2026, which is within 3 days of receipt.','gemini','gemini-3.5-flash','2026-11-03 06:33:47'),('MSG002','Cloudhost Billing sent an automated payment receipt confirming receipt of INR 14,750.00 for October 2026.','information','Confirm receipt of payment for Cloudhost Business plan','low',0,0,'neutral',NULL,'Automated payment receipt for informational purposes only.','gemini','gemini-3.5-flash','2026-11-03 06:33:47'),('MSG003','Arjun Mehta alerted the team that Sunrise Dental contact form submissions are not reaching their inbox and requested a check of spam folders and SMTP settings.','urgent_issue','Investigate missing contact form submissions for Sunrise Dental','high',1,1,'neutral','Hi Arjun,\n\nThank you for flagging this issue regarding Sunrise Dental\'s contact form. Our technical support team is investigating the problem right away by reviewing the website\'s SMTP configuration and checking mail deliverability and spam filters. We will identify the cause of the delivery failure and post an update in this thread as soon as it is resolved.\n\nBest regards,\nActionFlow Team','Contact form submissions are failing for a client, representing an active technical issue.','gemini','gemini-3.5-flash','2026-11-03 06:33:47'),('MSG004','Meera Iyer reported that Brightpath Edu was double-charged INR 62,000 for invoice INV-2026-0412 and requested a refund.','billing','Resolve duplicate billing charge and process client refund','high',1,1,'negative','Dear Meera,\n\nThank you for bringing this payment issue to our attention, and please accept our apologies for the inconvenience caused by the duplicate debit. We have received your attached bank statement, and our finance department is reviewing the transactions for invoice INV-2026-0412 right now. We will process the full refund of INR 62,000 immediately and notify you as soon as the transaction is confirmed.\n\nBest regards,\nActionFlow Team','An upset client is escalating a financial error involving duplicate bank charges.','gemini','gemini-3.5-flash','2026-11-03 06:33:47'),('MSG005','Daniel Okafor invited the team to a project kickoff call for the customer portal on Wednesday, 28 October at 3:00 PM IST.','meeting','Confirm team attendance for kickoff meeting','high',1,1,'positive','Dear Daniel,\n\nThank you for sending the invitation for the new customer portal project kickoff call. We are looking forward to collaborating with the Lagos Wave team. We confirm that our project representatives will attend the meeting scheduled for Wednesday, 28 October at 3:00 PM IST using the video link provided. We look forward to discussing the scope and agreeing on key milestones.\n\nBest regards,\nActionFlow Team','The meeting is scheduled for tomorrow, requiring immediate attendance confirmation.','gemini','gemini-3.5-flash','2026-11-03 06:33:47'),('MSG006','Weekly design newsletter containing industry trends and a promotional discount code.','promotional','Marketing newsletter','low',0,0,'neutral',NULL,'This is a promotional newsletter with no required action.','gemini','gemini-3.1-flash-lite','2026-11-03 06:33:58'),('MSG007','Client expressed gratitude for the recent checkout page fix.','acknowledgement','Thank you note','low',0,0,'positive',NULL,'This is a positive feedback message requiring no further action.','gemini','gemini-3.1-flash-lite','2026-11-03 06:33:58'),('MSG008','Client reports a 502 Bad Gateway error on their website during a flash sale.','urgent_issue','Report website outage','high',1,1,'negative','Dear Karthik, thank you for alerting us. We have prioritized this issue and our engineering team is currently investigating the 502 error to restore your website as quickly as possible. We understand the urgency due to your flash sale and will call you at 98450 00000 immediately once the site is back up. We will keep you updated on our progress. Best regards,\nActionFlow Team','Active website outage during a flash sale causing financial loss.','gemini','gemini-3.1-flash-lite','2026-11-03 06:33:58'),('MSG009','Internal notice regarding office closure for Diwali.','information','Office holiday announcement','low',0,0,'neutral',NULL,'Informational notice about upcoming office hours.','gemini','gemini-3.1-flash-lite','2026-11-03 06:33:58'),('MSG010','Client request for a Q4 analytics report covering traffic, conversions, and ad spend.','client_request','Request analytics report','medium',1,1,'neutral','Hi Ananya, thank you for your request. We have received your requirements for the Q4 analytics report and will prepare the data regarding traffic, conversion rates, and ad spend by channel. We will ensure the report is delivered to you by 6 November. Please let us know if you have any additional requirements in the meantime. Best regards,\nActionFlow Team','Standard client request for reporting with a defined deadline.','gemini','gemini-3.1-flash-lite','2026-11-03 06:33:58'),('MSG011','Vikram Singh is requesting an update on the SEO audit proposal for travel packages.','follow_up','Request status update on proposal','medium',1,1,'neutral','Dear Vikram,\n\nThank you for following up. Please accept our apologies for the delay in getting back to you. We are currently finalizing the scope and pricing details for your SEO audit and will have that information sent over to you shortly. We appreciate your patience and look forward to working with you on this project.\n\nBest regards,\nActionFlow Team','Standard client follow-up on a pending proposal.','gemini','gemini-3.1-flash-lite','2026-11-03 06:34:30'),('MSG012','Rohan Das reported a critical payment gateway failure on the Craftkart site.','urgent_issue','Report payment gateway outage','high',0,1,'negative',NULL,'Active service outage causing financial loss for the client.','gemini','gemini-3.1-flash-lite','2026-11-03 06:34:30'),('MSG013','Fatima Sheikh requested updates to the pricing page, a revised quotation, and a review call.','client_request','Request website updates, quotation, and meeting','high',1,1,'neutral','Dear Fatima,\n\nThank you for your email. We have received the new plan names and will ensure the pricing page is updated by the end of the day tomorrow. We are also working on the revised mobile app quotation and will send that over shortly. Regarding the review call, we would be happy to meet early next week; please let us know your availability for Monday or Tuesday.\n\nBest regards,\nActionFlow Team','Includes a specific deadline for tomorrow.','gemini','gemini-3.1-flash-lite','2026-11-03 06:34:30'),('MSG014','Product team provided release notes for Nimbus CMS v3.8.','information','Notify team of software update','low',0,0,'neutral',NULL,'Informational update with no required action.','gemini','gemini-3.1-flash-lite','2026-11-03 06:34:30'),('MSG015','Hannah Müller reported a security vulnerability on the staging site.','urgent_issue','Report security vulnerability','high',1,1,'negative','Dear Hannah,\n\nThank you for bringing this critical security issue to our attention. We have escalated this to our engineering team immediately and are currently working to restrict access to the staging admin panel and rotate the necessary credentials. We will confirm once these security measures have been implemented. We appreciate your vigilance in keeping the project secure.\n\nBest regards,\nActionFlow Team','Critical security risk involving exposed customer data.','gemini','gemini-3.1-flash-lite','2026-11-03 06:34:30'),('MSG016','The sender acknowledged a previous message.','acknowledgement','Acknowledge receipt of information','low',0,0,'positive',NULL,'This is a simple acknowledgement with no further action required.','gemini','gemini-3.1-flash-lite','2026-11-03 06:34:35'),('MSG017','Client requested Q4 analytics report for an upcoming board meeting.','client_request','Request Q4 analytics report','medium',1,1,'neutral','Dear Siddharth, thank you for your email. We have received your request for the Q4 analytics report covering traffic, conversions, and spend per channel. Our team is currently compiling this data for you. We will ensure the report is delivered to you well before your board meeting on Wednesday. Please let us know if there are any specific metrics you would like us to highlight in the summary. Best regards,\nActionFlow Team','Standard client request for reporting with a specific deadline.','gemini','gemini-3.1-flash-lite','2026-11-03 06:34:35'),('MSG018','Client requested to reschedule the design review meeting.','meeting','Reschedule design review meeting','medium',1,1,'neutral','Hi Neha, thank you for reaching out. We have noted your request to reschedule the design review. We are checking our team\'s availability for Tuesday, 3 November at 4:00 PM IST and will confirm shortly if this slot works for us. We appreciate your flexibility and look forward to the session. Best regards,\nActionFlow Team','Standard meeting coordination.','gemini','gemini-3.1-flash-lite','2026-11-03 06:34:35'),('MSG019','Client is complaining about a delayed website delivery and requesting a new timeline.','complaint','Request status update and revised delivery timeline','high',1,1,'negative','Dear Pradeep,\n\nWe sincerely apologize for the delay in delivering your online ordering website and for the lack of updates. We understand that the festive season is a crucial time for Joshi Sweets and deeply regret the impact this delay is having on your business.\n\nWe are looking into the status of your project right away. As requested, we will send you a revised delivery timeline along with a full explanation for the slip by Monday.\n\nWe appreciate your patience and remain committed to getting your website live as quickly as possible.\n\nBest regards,\nActionFlow Team','Client is expressing significant disappointment due to missed deadlines and business impact.','gemini','gemini-3.1-flash-lite','2026-11-03 06:36:23'),('MSG020','Automated receipt for domain renewal.','information','Provide payment receipt','low',0,0,'neutral',NULL,'Automated notification requiring no action.','gemini','gemini-3.1-flash-lite','2026-11-03 06:34:35'),('MSG021','Isha Malhotra requested adding a testimonials section to the Bloom Boutique home page, mentioning she will send customer quotes separately.','client_request','Request addition of a testimonials section to the home page','medium',1,1,'positive','Hi Isha,\n\nThank you for reaching out! We would be happy to add a testimonials section to your home page. Whenever you are ready, please send over the customer quotes and we will get that implemented for you.\n\nLet us know if you have any preferred design styles or layouts in mind.\n\nBest regards,\nActionFlow Team','Standard client feature request with no urgent deadline.','gemini','gemini-3.5-flash','2026-11-03 06:35:02'),('MSG022','Ritu Agarwal sent a thank-you message expressing satisfaction with the newly delivered catalogue site.','acknowledgement','Express gratitude for successful delivery of catalogue website','low',0,0,'positive',NULL,'Positive acknowledgement email requiring no further action.','gemini','gemini-3.5-flash','2026-11-03 06:35:02'),('MSG023','Tomasz Kowalski requested a quotation, effort estimate, and translation plugin recommendations for adding Hindi and Polish language support to their website.','client_request','Request quotation and recommendations for website multilingual support','medium',1,1,'neutral','Hi Tomasz,\n\nThank you for reaching out to us. We would be delighted to assist with adding Hindi and Polish language support to your website. Our team is currently preparing a detailed effort estimate and quotation, along with our recommendations for translation plugins.\n\nWe will get back to you with the details shortly.\n\nBest regards,\nActionFlow Team','Standard client inquiry for a quotation and technical advice.','gemini','gemini-3.5-flash','2026-11-03 06:35:02'),('MSG024','Arjun Mehta requested the staging URL and login credentials for the new Greenleaf store prior to a 10 AM meeting tomorrow.','client_request','Request staging URL and credentials for upcoming client meeting','high',1,1,'neutral','Hi Arjun,\n\nThanks for reaching out. We are retrieving the staging URL and login details for the new Greenleaf store and will send them over to you right away so you are set for tomorrow\'s 10 AM call.\n\nBest regards,\nActionFlow Team','Specific deadline stated for tomorrow at 10 AM (within 2 days).','gemini','gemini-3.5-flash','2026-11-03 06:35:02'),('MSG025','Lakshmi Venkatesh shared an update regarding the remote work and leave policy taking effect on 1 December, noting no action is required.','information','Announce updated remote work and leave policy effective December 1','low',0,0,'neutral',NULL,'Informational policy announcement explicitly stating no action is required.','gemini','gemini-3.5-flash','2026-11-03 06:35:02'),('MSG026','Rahul Sharma requests the completion of the payment gateway integration and the delivery of the staging URL before Thursday.','client_request','Complete payment gateway integration and provide staging URL','medium',1,1,'neutral','Dear Rahul,\n\nThank you for contacting us regarding your website launch. We have received your request to complete the payment gateway integration. Our team is working on it, and we will share the staging URL with you before Thursday as requested so you can review the integration.\n\nPlease feel free to reach out if you have any questions or additional details to share in the meantime.\n\nBest regards,\nActionFlow Team','The request has a deadline on Thursday, November 5, which is more than 2 days away.','gemini','gemini-3.5-flash','2026-11-03 06:35:36'),('MSG027','Elena Rossi sent a reminder requesting the final brand guidelines PDF by November 6 for her print vendor.','follow_up','Request final brand guidelines PDF for print vendor','medium',1,1,'neutral','Dear Elena,\n\nThank you for following up with us regarding the brand guidelines PDF. We appreciate your patience while we prepare the final file. We are currently finalizing the document and will ensure it is sent to you well before 6 November so your print vendor has everything they need.\n\nPlease let us know if you need any other assets in the meantime.\n\nBest regards,\nActionFlow Team','The deadline is November 6, which is more than 2 days from the sent date.','gemini','gemini-3.5-flash','2026-11-03 06:35:36'),('MSG028','Aditya Verma reported a bug where the mobile menu does not open on iPhone product pages, requesting a fix before November 9 and checks on blog and checkout pages.','client_request','Report mobile menu bug on iPhone and request fix and site-wide checks','medium',1,1,'neutral','Dear Aditya,\n\nThank you for notifying us about the mobile menu issue on iPhone product pages and for attaching the screenshots. We are investigating the bug immediately to get it resolved well before your campaign starts on 9 November. We will also inspect the blog and checkout pages to verify if the issue affects those sections and share our findings with you shortly.\n\nBest regards,\nActionFlow Team','The issue needs to be resolved before the campaign on November 9, which is more than 2 days away.','gemini','gemini-3.5-flash','2026-11-03 06:35:36'),('MSG029','Vikram Singh notified the team that the weekly sync has been moved to Thursday, November 5 at 11:30 AM and asked for confirmation.','meeting','Reschedule weekly sync meeting to Thursday, November 5','medium',1,1,'neutral','Dear Vikram,\n\nThank you for the notification regarding the updated time for our weekly sync. We have checked our schedule, and Thursday, 5 November at 11:30 AM works well for our team. We will join the meeting using the existing link as discussed.\n\nPlease let us know if any additional topics need to be added to the agenda prior to our call.\n\nBest regards,\nActionFlow Team','The rescheduled meeting date of November 5 is more than 2 days away.','gemini','gemini-3.5-flash','2026-11-03 06:35:36'),('MSG030','Naveen Prakash invited the team to a Sprint Planning session on Wednesday, November 4 from 10:00 to 11:00 AM IST and asked for confirmation and agenda additions.','meeting','Invite team to Sprint Planning meeting and gather agenda topics','high',1,1,'neutral','Hi Naveen,\n\nThank you for sharing the details and draft agenda for the upcoming Sprint Planning session. We confirm our attendance for Wednesday, 4 November from 10:00 to 11:00 AM IST. Our team is currently reviewing the attached draft agenda, and we will add any additional discussion topics directly to the document before the meeting starts.\n\nBest regards,\nActionFlow Team','The meeting is scheduled for tomorrow, Wednesday, November 4, which is within 2 days of the message.','gemini','gemini-3.5-flash','2026-11-03 06:35:36');
/*!40000 ALTER TABLE `message_analyses` ENABLE KEYS */;
UNLOCK TABLES;
DROP TABLE IF EXISTS `messages`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `messages` (
  `id` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL,
  `type` enum('email','message') COLLATE utf8mb4_unicode_ci NOT NULL,
  `sender_name` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `sender_email` varchar(320) COLLATE utf8mb4_unicode_ci NOT NULL,
  `recipient` varchar(320) COLLATE utf8mb4_unicode_ci NOT NULL,
  `subject` varchar(500) COLLATE utf8mb4_unicode_ci NOT NULL,
  `sent_at` datetime NOT NULL,
  `date_raw` varchar(40) COLLATE utf8mb4_unicode_ci NOT NULL,
  `content` text COLLATE utf8mb4_unicode_ci NOT NULL,
  `attachments` json NOT NULL,
  `extra` json DEFAULT NULL,
  `source` enum('json','manual','gmail') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'json',
  `import_batch_id` int DEFAULT NULL,
  `created_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `idx_messages_sent_at` (`sent_at`),
  KEY `fk_messages_batch` (`import_batch_id`),
  FULLTEXT KEY `ft_messages_text` (`subject`,`content`,`sender_name`),
  CONSTRAINT `fk_messages_batch` FOREIGN KEY (`import_batch_id`) REFERENCES `import_batches` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

LOCK TABLES `messages` WRITE;
/*!40000 ALTER TABLE `messages` DISABLE KEYS */;
INSERT INTO `messages` VALUES ('MSG001','email','Priya Nair','priya.nair@greenleaf-organics.example','team@nimbusdigital.example','Diwali sale banner copy','2026-10-27 03:42:00','2026-10-27T09:12:00+05:30','Hi team, I have attached the final copy for the Diwali sale banner. Please update the homepage hero banner with this text and the 20% off code DIWALI20 by 30 October so it is live before the weekend traffic. Let me know if the character count is a problem for the mobile layout.','[{\"sizeKb\": 46, \"filename\": \"diwali_banner_copy_v3.docx\", \"mimeType\": \"application/vnd.openxmlformats-officedocument.wordprocessingml.document\"}]',NULL,'json',1,'2026-11-03 06:32:11'),('MSG002','email','Cloudhost Billing','no-reply@billing.cloudhost.example','team@nimbusdigital.example','Payment received - Invoice CH-88231','2026-10-27 04:35:00','2026-10-27T10:05:00+05:30','This is an automated receipt. We have received your payment of INR 14,750.00 for the Cloudhost Business plan (October 2026). No further action is required. This mailbox is not monitored, so please do not reply to this message.','[]',NULL,'json',1,'2026-11-03 06:32:11'),('MSG003','message','Arjun Mehta','arjun.mehta@nimbusdigital.example','team-chat','Quick ping','2026-10-27 06:10:00','2026-10-27T11:40:00+05:30','hey, Sunrise Dental says the contact form submissions aren\'t reaching their inbox. could someone check if they\'re landing in spam or if the SMTP settings changed?','[]',NULL,'json',1,'2026-11-03 06:32:11'),('MSG004','email','Meera Iyer','meera.iyer@brightpath-edu.example','team@nimbusdigital.example','Charged twice for October invoice','2026-10-27 08:50:00','2026-10-27T14:20:00+05:30','Hello, I noticed that our account was debited twice for invoice INV-2026-0412 (INR 62,000 each time). I have attached the bank statement showing both transactions. This is quite frustrating as it affects our month-end books. Kindly look into it and confirm how the duplicate payment will be refunded.','[{\"sizeKb\": 218, \"filename\": \"bank_statement_oct_2026.pdf\", \"mimeType\": \"application/pdf\"}]',NULL,'json',1,'2026-11-03 06:32:11'),('MSG005','email','Daniel Okafor','daniel.okafor@lagoswave.example','team@nimbusdigital.example','Kickoff call - Wednesday 28 October, 3:00 PM IST','2026-10-27 11:15:00','2026-10-27T16:45:00+05:30','Dear Nimbus team, I would like to invite you to our project kickoff call on Wednesday, 28 October at 3:00 PM IST (10:30 AM WAT). We will walk through the scope for the new customer portal and agree on milestones. The video link is https://meet.example/lagoswave-kickoff. Please confirm who from your side will attend.','[]',NULL,'json',1,'2026-11-03 06:32:11'),('MSG006','email','DesignDeck Weekly','hello@designdeck.example','team@nimbusdigital.example','This week: 12 landing page trends and 30% off Pro templates','2026-10-28 03:25:00','2026-10-28T08:55:00+05:30','Your weekly dose of design inspiration is here! Explore 12 landing page trends for 2026, plus enjoy 30% off all Pro templates until Sunday with code WEEKLY30. You are receiving this email because you subscribed to DesignDeck Weekly. Unsubscribe at any time.','[]',NULL,'json',1,'2026-11-03 06:32:11'),('MSG007','message','Sneha Kulkarni','sneha.kulkarni@urbancrate.example','team-chat','Thanks!','2026-10-28 04:45:00','2026-10-28T10:15:00+05:30','Just wanted to say thanks for the quick fix on the checkout page yesterday. Everything looks great now!','[]',NULL,'json',1,'2026-11-03 06:32:11'),('MSG008','email','Karthik Reddy','karthik.reddy@hyderabad-handloom.example','team@nimbusdigital.example','URGENT: Website is down (502 error)','2026-10-28 06:00:00','2026-10-28T11:30:00+05:30','Our entire website has been showing a 502 Bad Gateway error since about 11:00 AM. We are running a flash sale today and every minute of downtime is costing us orders. Please look into this immediately and call me on 98450 00000 as soon as it is back up.','[]',NULL,'json',1,'2026-11-03 06:32:11'),('MSG009','email','Lakshmi Venkatesh','admin@nimbusdigital.example','team@nimbusdigital.example','Office holiday notice - Diwali break','2026-10-28 07:40:00','2026-10-28T13:10:00+05:30','Dear all, please note that the Nimbus Digital office will be closed on Monday, 9 November for the Diwali break. Normal working hours resume on Tuesday, 10 November. For anything critical during the break, the on-call roster is available on the intranet. Wishing everyone a safe and happy Diwali!','[]',NULL,'json',1,'2026-11-03 06:32:11'),('MSG010','email','Ananya Banerjee','ananya.banerjee@greenleaf-organics.example','team@nimbusdigital.example','Q4 analytics report','2026-10-28 10:00:00','2026-10-28T15:30:00+05:30','Hi team, could you please prepare and share the Q4 analytics report for the Greenleaf Organics campaigns? We need traffic, conversion rate and ad spend by channel. The deadline on our side is 6 November.','[]',NULL,'json',1,'2026-11-03 06:32:11'),('MSG011','email','Vikram Singh','vikram.singh@rajputana-travels.example','team@nimbusdigital.example','Re: SEO audit proposal','2026-10-28 11:35:00','2026-10-28T17:05:00+05:30','Hello, following up on my email from last week regarding the SEO audit proposal for our travel packages pages. I have not heard back yet. Could you share an update on the scope and pricing when you can?','[]',NULL,'json',1,'2026-11-03 06:32:11'),('MSG012','message','Rohan Das','rohan.das@nimbusdigital.example','team-chat','Payments failing!!','2026-10-29 03:50:00','2026-10-29T09:20:00+05:30','Urgent - Craftkart\'s payment gateway is returning error 500 on checkout and customers are dropping off. started around 9. can someone with gateway access look at it right now?','[]',NULL,'json',1,'2026-11-03 06:32:11'),('MSG013','email','Fatima Sheikh','fatima.sheikh@zenfit-studio.example','team@nimbusdigital.example','Pricing page, quotation and review call','2026-10-29 05:10:00','2026-10-29T10:40:00+05:30','Hi, three things from our side. First, please update the pricing page with the new plan names from the attached sheet; we need this by end of day tomorrow. Second, send us the revised quotation for the mobile app. Third, can we schedule a short review call early next week to go over the new designs?','[{\"sizeKb\": 24, \"filename\": \"new_plan_names.xlsx\", \"mimeType\": \"application/vnd.openxmlformats-officedocument.spreadsheetml.sheet\"}]',NULL,'json',1,'2026-11-03 06:32:11'),('MSG014','email','Nimbus Product Team','product@nimbusdigital.example','team@nimbusdigital.example','Release notes: Nimbus CMS v3.8','2026-10-29 06:55:00','2026-10-29T12:25:00+05:30','Nimbus CMS v3.8 is now live for all client sites. Highlights: faster media library, bulk redirects editor, and improved accessibility on form blocks. Full release notes are attached for reference. No action is needed; existing sites were upgraded automatically.','[{\"sizeKb\": 132, \"filename\": \"nimbus_cms_v3.8_release_notes.pdf\", \"mimeType\": \"application/pdf\"}]',NULL,'json',1,'2026-11-03 06:32:11'),('MSG015','email','Hannah Müller','hannah.mueller@securenord.example','team@nimbusdigital.example','Security issue: staging admin panel is publicly accessible','2026-10-29 08:30:00','2026-10-29T14:00:00+05:30','During a routine check we found that the admin panel of your staging site for our project is reachable from the internet without any authentication, and it exposes customer test data. This is a serious security risk. Please restrict access and rotate any shared credentials before the end of the day today. A screenshot is attached.','[{\"sizeKb\": 312, \"filename\": \"staging_admin_exposed.png\", \"mimeType\": \"image/png\"}]',NULL,'json',1,'2026-11-03 06:32:11'),('MSG016','message','Arjun Mehta','arjun.mehta@nimbusdigital.example','team-chat','Re: contact form','2026-10-29 10:40:00','2026-10-29T16:10:00+05:30','Noted, thanks.','[]',NULL,'json',1,'2026-11-03 06:32:11'),('MSG017','email','Siddharth Rao','siddharth.rao@greenleaf-organics.example','team@nimbusdigital.example','Need Q4 numbers for board meeting','2026-10-30 03:35:00','2026-10-30T09:05:00+05:30','Good morning. I will be presenting to our board and need the Q4 analytics report for our digital campaigns, covering traffic, conversions and spend per channel. Please send it over before Wednesday\'s board meeting.','[]',NULL,'json',1,'2026-11-03 06:32:11'),('MSG018','email','Neha Kapoor','neha.kapoor@pixelmint.example','team@nimbusdigital.example','Reschedule: design review','2026-10-30 05:00:00','2026-10-30T10:30:00+05:30','Hi, I need to reschedule our design review that was set for Monday, 2 November at 11:00 AM. Would Tuesday, 3 November at 4:00 PM IST work for your team? Same video link will be used. Please confirm if the new slot is fine.','[]',NULL,'json',1,'2026-11-03 06:32:11'),('MSG019','email','Pradeep Joshi','pradeep.joshi@joshi-sweets.example','team@nimbusdigital.example','Website still not delivered','2026-10-30 06:45:00','2026-10-30T12:15:00+05:30','We were promised delivery of the online ordering website on 23 October and it is now a week later with no update. Our festive season is starting and we are losing orders. I am very disappointed with this delay. Please send me a revised delivery timeline by Monday along with the reason for the slip.','[]',NULL,'json',1,'2026-11-03 06:32:11'),('MSG020','email','NameVault Registrar','receipts@namevault.example','team@nimbusdigital.example','Domain renewal receipt - nimbusdigital.example','2026-10-30 09:30:00','2026-10-30T15:00:00+05:30','Thank you for your payment. Your domain nimbusdigital.example has been renewed for 1 year. Your receipt is attached. This is an automated message and no action is required.','[{\"sizeKb\": 58, \"filename\": \"receipt_NV-552019.pdf\", \"mimeType\": \"application/pdf\"}]',NULL,'json',1,'2026-11-03 06:32:11'),('MSG021','message','Isha Malhotra','isha.malhotra@bloomboutique.example','team-chat','Small addition','2026-10-31 04:35:00','2026-10-31T10:05:00+05:30','Hi! Sometime soon could you also add a testimonials section to our home page? No rush at all, whenever you get a chance. I\'ll send the customer quotes separately.','[]',NULL,'json',1,'2026-11-03 06:32:11'),('MSG022','message','Ritu Agarwal','ritu.agarwal@agarwal-textiles.example','team-chat','Thank you','2026-10-31 06:00:00','2026-10-31T11:30:00+05:30','Thank you so much for delivering the new catalogue site. Our customers love it and the team is very happy with the whole experience!','[]',NULL,'json',1,'2026-11-03 06:32:11'),('MSG023','email','Tomasz Kowalski','tomasz.kowalski@polskatech.example','team@nimbusdigital.example','Multilingual support quote','2026-11-01 04:10:00','2026-11-01T09:40:00+05:30','Hello, we are considering adding Hindi and Polish versions of our website. Could you send us a quotation and a rough estimate of the effort involved? We would also like to know which translation plugins you recommend.','[]',NULL,'json',1,'2026-11-03 06:32:11'),('MSG024','message','Arjun Mehta','arjun.mehta@nimbusdigital.example','team-chat','Quick ping','2026-11-01 12:50:00','2026-11-01T18:20:00+05:30','Greenleaf wants to see the new store on staging in tomorrow\'s 10 AM call. Can someone share the staging URL and login with me before then?','[]',NULL,'json',1,'2026-11-03 06:32:11'),('MSG025','email','Lakshmi Venkatesh','admin@nimbusdigital.example','team@nimbusdigital.example','Policy update: remote work and leave','2026-11-02 03:20:00','2026-11-02T08:50:00+05:30','Hello everyone, for your information, the updated remote work and leave policy will take effect from 1 December. The key changes are two additional remote days per month and a simplified leave approval flow. The full policy is on the intranet. No action is required from you at this time.','[]',NULL,'json',1,'2026-11-03 06:32:11'),('MSG026','email','Rahul Sharma','rahul@example.com','team@nimbusdigital.example','Website Launch','2026-11-02 05:00:00','2026-11-02T10:30:00+05:30','Please complete the payment gateway integration and share the staging URL before Thursday.','[]',NULL,'json',1,'2026-11-03 06:32:11'),('MSG027','email','Elena Rossi','elena.rossi@milanostudio.example','team@nimbusdigital.example','Reminder: brand guidelines PDF','2026-11-02 06:40:00','2026-11-02T12:10:00+05:30','Hi, a gentle reminder about the brand guidelines PDF I requested on 20 October. Our print vendor needs the final file, so please send it to me by 6 November at the latest. Thank you for your help.','[]',NULL,'json',1,'2026-11-03 06:32:11'),('MSG028','email','Aditya Verma','aditya.verma@verma-fitness.example','team@nimbusdigital.example','Mobile menu bug on iPhone','2026-11-02 10:15:00','2026-11-02T15:45:00+05:30','The mobile menu does not open on product pages when using an iPhone; the screenshots are attached. Please fix this before our campaign starts on 9 November. Also, can you check whether the same problem affects the blog and checkout pages, and let us know what you find?','[{\"sizeKb\": 284, \"filename\": \"iphone_menu_bug_1.png\", \"mimeType\": \"image/png\"}, {\"sizeKb\": 301, \"filename\": \"iphone_menu_bug_2.png\", \"mimeType\": \"image/png\"}]',NULL,'json',1,'2026-11-03 06:32:11'),('MSG029','message','Vikram Singh','vikram.singh@rajputana-travels.example','team-chat','Call moved','2026-11-02 13:00:00','2026-11-02T18:30:00+05:30','Heads up, our weekly sync is moved to Thursday 5 November at 11:30 AM. Same meeting link as before. Does that slot work for you?','[]',NULL,'json',1,'2026-11-03 06:32:11'),('MSG030','email','Naveen Prakash','naveen.prakash@nimbusdigital.example','team@nimbusdigital.example','Invitation: Sprint planning, Wed 4 Nov','2026-11-03 03:45:00','2026-11-03T09:15:00+05:30','Hi all, sprint planning is scheduled for Wednesday, 4 November from 10:00 to 11:00 AM IST in the main conference room, with a video link for remote folks. The draft agenda is attached. Please confirm your attendance and add any agenda items you want to discuss.','[{\"sizeKb\": 37, \"filename\": \"sprint_planning_agenda.docx\", \"mimeType\": \"application/vnd.openxmlformats-officedocument.wordprocessingml.document\"}]',NULL,'json',1,'2026-11-03 06:32:11');
/*!40000 ALTER TABLE `messages` ENABLE KEYS */;
UNLOCK TABLES;
DROP TABLE IF EXISTS `task_dependencies`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `task_dependencies` (
  `task_id` int NOT NULL,
  `depends_on_id` int NOT NULL,
  `created_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`task_id`,`depends_on_id`),
  KEY `fk_dep_on` (`depends_on_id`),
  CONSTRAINT `fk_dep_on` FOREIGN KEY (`depends_on_id`) REFERENCES `tasks` (`id`) ON DELETE CASCADE,
  CONSTRAINT `fk_dep_task` FOREIGN KEY (`task_id`) REFERENCES `tasks` (`id`) ON DELETE CASCADE,
  CONSTRAINT `chk_dep_self` CHECK ((`task_id` <> `depends_on_id`))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

LOCK TABLES `task_dependencies` WRITE;
/*!40000 ALTER TABLE `task_dependencies` DISABLE KEYS */;
INSERT INTO `task_dependencies` VALUES (22,21,'2026-11-03 06:36:23');
/*!40000 ALTER TABLE `task_dependencies` ENABLE KEYS */;
UNLOCK TABLES;
DROP TABLE IF EXISTS `tasks`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `tasks` (
  `id` int NOT NULL AUTO_INCREMENT,
  `message_id` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `title` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `description` text COLLATE utf8mb4_unicode_ci,
  `priority` enum('high','medium','low') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'medium',
  `status` enum('pending','in_progress','completed') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'pending',
  `due_date` date DEFAULT NULL,
  `due_date_evidence` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `source` enum('ai','manual') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'ai',
  `user_modified` tinyint(1) NOT NULL DEFAULT '0',
  `duplicate_of` int DEFAULT NULL,
  `created_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `completed_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_tasks_status` (`status`),
  KEY `idx_tasks_priority` (`priority`),
  KEY `idx_tasks_due` (`due_date`),
  KEY `fk_tasks_message` (`message_id`),
  KEY `fk_tasks_duplicate` (`duplicate_of`),
  FULLTEXT KEY `ft_tasks_text` (`title`,`description`),
  CONSTRAINT `fk_tasks_duplicate` FOREIGN KEY (`duplicate_of`) REFERENCES `tasks` (`id`) ON DELETE SET NULL,
  CONSTRAINT `fk_tasks_message` FOREIGN KEY (`message_id`) REFERENCES `messages` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB AUTO_INCREMENT=29 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

LOCK TABLES `tasks` WRITE;
/*!40000 ALTER TABLE `tasks` DISABLE KEYS */;
INSERT INTO `tasks` VALUES (1,'MSG001','Update homepage hero banner with Diwali copy','Apply the text from diwali_banner_copy_v3.docx and code DIWALI20 to the homepage hero banner while checking mobile layout character limits.','high','pending','2026-10-30','by 30 October','ai',0,NULL,'2026-11-03 06:33:47','2026-11-03 06:33:47',NULL),(2,'MSG003','Investigate Sunrise Dental contact form delivery issue','Check if form submissions are landing in spam folders or if SMTP settings have changed for Sunrise Dental.','high','pending',NULL,NULL,'ai',0,NULL,'2026-11-03 06:33:47','2026-11-03 06:33:47',NULL),(3,'MSG004','Investigate duplicate charge on invoice INV-2026-0412','Review the attached bank statement, verify duplicate debits for INV-2026-0412, and initiate the refund of INR 62,000.','high','pending',NULL,NULL,'ai',0,NULL,'2026-11-03 06:33:47','2026-11-03 06:33:47',NULL),(4,'MSG005','Confirm attendees for Lagos Wave kickoff meeting','Select team members to attend the kickoff meeting on Wednesday, 28 October at 3:00 PM IST and send attendance confirmation.','high','pending','2026-10-28','Wednesday, 28 October at 3:00 PM IST','ai',0,NULL,'2026-11-03 06:33:47','2026-11-03 06:33:47',NULL),(5,'MSG008','Investigate and resolve 502 error','Diagnose the cause of the 502 Bad Gateway error on the client\'s website and restore service immediately.','high','pending',NULL,NULL,'ai',0,NULL,'2026-11-03 06:33:58','2026-11-03 06:33:58',NULL),(6,'MSG008','Call client upon restoration','Contact the client at 98450 00000 as soon as the website is back online.','high','pending',NULL,NULL,'ai',0,NULL,'2026-11-03 06:33:58','2026-11-03 06:33:58',NULL),(7,'MSG010','Prepare Q4 analytics report','Compile traffic, conversion rate, and ad spend by channel for Greenleaf Organics campaigns.','medium','pending','2026-11-06','6 November','ai',0,NULL,'2026-11-03 06:33:58','2026-11-03 06:33:58',NULL),(8,'MSG011','Prepare SEO audit proposal','Draft and send the SEO audit proposal for the travel packages pages including scope and pricing.','medium','pending',NULL,NULL,'ai',0,NULL,'2026-11-03 06:34:30','2026-11-03 06:34:30',NULL),(9,'MSG012','Investigate and fix payment gateway error','Diagnose the 500 error on the Craftkart payment gateway and restore functionality immediately.','high','pending',NULL,NULL,'ai',0,NULL,'2026-11-03 06:34:30','2026-11-03 06:34:30',NULL),(10,'MSG013','Update pricing page','Update the pricing page with the new plan names provided in the attached spreadsheet.','high','pending','2026-10-30','end of day tomorrow','ai',0,NULL,'2026-11-03 06:34:30','2026-11-03 06:34:30',NULL),(11,'MSG013','Send revised mobile app quotation','Prepare and send the revised quotation for the mobile app project.','medium','pending',NULL,NULL,'ai',0,NULL,'2026-11-03 06:34:30','2026-11-03 06:34:30',NULL),(12,'MSG013','Schedule review call','Coordinate a time early next week to review the new designs with the client.','medium','pending',NULL,NULL,'ai',0,NULL,'2026-11-03 06:34:30','2026-11-03 06:34:30',NULL),(13,'MSG015','Secure staging admin panel','Restrict public access to the staging admin panel and rotate all shared credentials.','high','pending','2026-10-29','end of the day today','ai',0,NULL,'2026-11-03 06:34:30','2026-11-03 06:34:30',NULL),(14,'MSG017','Prepare Q4 analytics report','Compile traffic, conversion, and spend per channel data for the Q4 digital campaigns.','medium','pending','2026-11-04','before Wednesday\'s board meeting','ai',0,7,'2026-11-03 06:34:35','2026-11-03 06:34:35',NULL),(15,'MSG018','Confirm design review reschedule','Check team availability for Tuesday, 3 November at 4:00 PM IST and confirm the new slot with the client.','medium','pending',NULL,NULL,'ai',0,NULL,'2026-11-03 06:34:35','2026-11-03 06:34:35',NULL),(16,'MSG019','Provide revised delivery timeline','Draft a response explaining the delay and provide a firm, revised delivery date for the online ordering website.','high','pending','2026-11-02','by Monday','ai',0,NULL,'2026-11-03 06:34:35','2026-11-03 06:34:35',NULL),(17,'MSG021','Add testimonials section to Bloom Boutique home page','Design and implement a testimonials section on the Bloom Boutique home page once customer quotes are received.','medium','pending',NULL,NULL,'ai',0,NULL,'2026-11-03 06:35:02','2026-11-03 06:35:02',NULL),(18,'MSG023','Prepare quotation and effort estimate for multilingual support','Scope the effort and create a formal quotation for adding Hindi and Polish versions to the client website.','medium','pending',NULL,NULL,'ai',0,NULL,'2026-11-03 06:35:02','2026-11-03 06:35:02',NULL),(19,'MSG023','Recommend translation plugins for Hindi and Polish support','Research and compile recommended translation plugins suitable for the client\'s website architecture.','medium','pending',NULL,NULL,'ai',0,NULL,'2026-11-03 06:35:02','2026-11-03 06:35:02',NULL),(20,'MSG024','Share Greenleaf store staging URL and login credentials','Provide Arjun with the staging link and credentials for the new Greenleaf store before the 10 AM call.','high','pending','2026-11-02','tomorrow\'s 10 AM call','ai',0,NULL,'2026-11-03 06:35:02','2026-11-03 06:35:02',NULL),(21,'MSG026','Complete payment gateway integration','Finish setting up and integrating the payment gateway for the client\'s website.','medium','pending','2026-11-05','before Thursday','ai',0,NULL,'2026-11-03 06:35:36','2026-11-03 06:35:36',NULL),(22,'MSG026','Share staging URL with client','Send the completed staging URL to Rahul Sharma once the payment integration is ready.','medium','pending','2026-11-05','before Thursday','ai',0,NULL,'2026-11-03 06:35:36','2026-11-03 06:35:36',NULL),(23,'MSG027','Send brand guidelines PDF to client','Deliver the final brand guidelines PDF to Elena Rossi for her print vendor.','medium','pending','2026-11-06','by 6 November','ai',0,NULL,'2026-11-03 06:35:36','2026-11-03 06:35:36',NULL),(24,'MSG028','Fix iPhone mobile menu bug on product pages','Resolve the issue preventing the mobile menu from opening on product pages when viewed on an iPhone.','medium','pending','2026-11-09','before our campaign starts on 9 November','ai',0,NULL,'2026-11-03 06:35:36','2026-11-03 06:35:36',NULL),(25,'MSG028','Check blog and checkout pages for mobile menu bug','Test the blog and checkout pages on iPhone devices to check if the mobile menu bug is present.','medium','pending','2026-11-09','before our campaign starts on 9 November','ai',0,NULL,'2026-11-03 06:35:36','2026-11-03 06:35:36',NULL),(26,'MSG029','Confirm weekly sync time slot','Check team availability and confirm attendance for the rescheduled weekly sync on Thursday, 5 November at 11:30 AM.','medium','pending','2026-11-05','Thursday 5 November at 11:30 AM','ai',0,NULL,'2026-11-03 06:35:36','2026-11-03 06:35:36',NULL),(27,'MSG030','Confirm attendance for Sprint Planning','Confirm attendance for the Sprint Planning meeting scheduled for Wednesday, 4 November from 10:00 to 11:00 AM IST.','high','pending','2026-11-04','Wednesday, 4 November from 10:00 to 11:00 AM IST','ai',0,NULL,'2026-11-03 06:35:36','2026-11-03 06:35:36',NULL),(28,'MSG030','Add agenda items for Sprint Planning','Review the attached draft agenda and add any proposed discussion topics prior to the meeting.','high','pending','2026-11-04','Wednesday, 4 November from 10:00 to 11:00 AM IST','ai',0,NULL,'2026-11-03 06:35:36','2026-11-03 06:35:36',NULL);
